export type CameraCraftReference = { title: string; url: string; source: string; accessed: string };
export type CameraCraftLesson = {
  summary: string;
  theory: { heading: string; body: string }[];
  objectives: string[];
  examples: string[];
  mistakes: string[];
  references: CameraCraftReference[];
};

const accessed = "2026-07-30";
const R = (title: string, url: string, source: string): CameraCraftReference => ({ title, url, source, accessed });
