const zeissCircle = R("Large Image Circle, Universal Usability", "https://lenspire.zeiss.com/cine/en/article/large-image-circle-universal-usability-the-compact-prime-cp-3-and-cinema-zoom-cz-2-lens-families", "ZEISS");
const arriLight = R("Lighting learning resources", "https://www.arri.com/en/learn-help/lighting/lighting-systems", "ARRI");
const djiSupport = R("Ronin support, specifications and operating guidance", "https://www.dji.com/support/product/ronin", "DJI");
